"""Differential fuzz: C collector (project/solver.py) vs dev/ref.py model."""
import json
import os
import random
import struct
import sys

sys.path.insert(0, '/workspace/project')
sys.path.insert(0, '/workspace/dev')
import ref            # noqa: E402
import solver         # noqa: E402
from wire import packet as build_packet  # noqa: E402

MASK = (1 << 24) - 1
PRIMS = ('allreduce', 'reduce', 'broadcast', 'barrier', 'allgather', 'reducescatter')


def rand_words(rng, D):
    return [rng.randrange(1 << 32) for _ in range(D)]


def corrupt(rng, frame, D):
    frame = bytearray(frame)
    kind = rng.randrange(9)
    if kind == 0 and frame:
        frame[rng.randrange(len(frame))] ^= 1 << rng.randrange(8)
    elif kind == 1:
        frame = frame[:rng.randrange(len(frame) + 1)]
    elif kind == 2:
        frame += bytes(rng.randrange(256) for _ in range(rng.randrange(1, 5)))
    elif kind == 3 and len(frame) > 20:
        frame[rng.randrange(14, min(len(frame), 34))] = rng.randrange(256)
    elif kind == 4 and len(frame) > 46:
        frame[42] = rng.choice([0x00, 0x05, 0x12, 0x10, 0xff])
    elif kind == 5 and len(frame) > 54:
        frame[50] = rng.randrange(256)          # apsn top byte
    elif kind == 6 and len(frame) > 50:
        frame[46] = rng.randrange(256)          # qpn top byte
    elif kind == 7 and len(frame) > 58:
        frame[-1 - rng.randrange(4)] ^= 0xff    # icrc
    else:
        frame = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 80)))
    return bytes(frame)


def gen_case(rng):
    prim = rng.choice(PRIMS)
    if prim == 'barrier':
        K, D = 1, 0
    else:
        D = rng.choice([0, 1, 2, 3, 5])
        if D == 0:
            D = 1
        K = rng.randrange(1, 13)
        if prim == 'reducescatter':
            K = 4 * rng.randrange(1, 4)
    N = rng.randrange(1, 7)
    mode = rng.choice([2, 3])
    root = rng.randrange(4)
    start = rng.choice([0, 1, 7, (1 << 24) - 3, (1 << 24) - 1, rng.randrange(1 << 24)])
    events = []
    n_events = rng.randrange(0, 22)
    for _ in range(n_events):
        pick = rng.random()
        if pick < 0.34:
            ev = {'op': 'data', 'rank': rng.randrange(4), 'p': rng.randrange(K)}
            if rng.random() < 0.3:
                ev['values'] = rand_words(rng, D)
            if rng.random() < 0.2:
                cnt = rng.randrange(1, 5)
                step = rng.choice([0, 1, 2, -1])
                lo, hi = 0, K - 1
                # ensure p + i*step stays in [0,K)
                if step >= 0:
                    if p := ev['p']:
                        pass
                    maxc = (K - 1 - ev['p']) // step + 1 if step else cnt
                    cnt = min(cnt, maxc)
                else:
                    maxc = ev['p'] // (-step) + 1
                    cnt = min(cnt, maxc)
                cnt = max(1, cnt)
                ev['count'] = cnt
                ev['step'] = step
                if rng.random() < 0.5:
                    ev['seed'] = rng.randrange(1 << 32)
            if rng.random() < 0.15:
                ev['xor'] = [[rng.randrange(0, 58 + 4 * D), rng.randrange(256)]
                             for _ in range(rng.randrange(1, 3))]
            events.append(ev)
        elif pick < 0.52:
            events.append({'op': 'ack', 'rank': rng.randrange(4),
                           'upto': rng.randrange(0, 3 * K + 2)})
        elif pick < 0.66:
            r = rng.randrange(4)
            style = rng.random()
            if style < 0.5:
                p = rng.randrange(K)
                body = struct.pack('!%dI' % D, *rand_words(rng, D))
                frame = build_packet(r, (start + p) & MASK, body)
            elif style < 0.75:
                n = rng.randrange(0, 3 * K + 2)
                frame = build_packet(r, (start + n - 1) & MASK, ack=True)
            else:
                frame = build_packet(rng.randrange(4), rng.randrange(1 << 24),
                                     struct.pack('!%dI' % D, *rand_words(rng, D)))
            if rng.random() < 0.55:
                frame = corrupt(rng, frame, D)
            events.append({'op': 'wire', 'rank': r, 'hex': frame.hex()})
        elif pick < 0.72:
            events.append({'op': 'budget', 'n': rng.choice([-1, 0, 1, 2, 3, 7, 1 << 20])})
        elif pick < 0.78:
            events.append({'op': 'flush'})
        elif pick < 0.86:
            events.append({'op': 'retry', 'rank': rng.randrange(4)})
        elif pick < 0.92:
            events.append({'op': 'snap', 'tag': rng.choice(['', 'a', 'x' * 64, 'tagé'])})
        else:
            p = rng.randrange(K)
            count = rng.randrange(1, min(9, K - p + 1))
            events.append({'op': 'train', 'p': p, 'count': count,
                           'width': rng.randrange(1, N + 1),
                           'ranks': rng.sample([0, 1, 2, 3], 4),
                           'reverse': rng.random() < 0.5,
                           'seed': rng.randrange(1 << 32)})
    return {'primitive': prim, 'mode': mode, 'root': root, 'segments': K,
            'words': D, 'capacity': N, 'start': start, 'events': events,
            'trace': rng.choice([0, 0, 3, 32])}


def equal(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(equal(x, y) for x, y in zip(a, b))
    return a == b


def diff(path, got, want, out):
    if isinstance(want, dict):
        for k in want:
            diff(path + '.' + str(k), got.get(k) if isinstance(got, dict) else None, want[k], out)
    elif isinstance(want, list):
        if not isinstance(got, list) or len(got) != len(want):
            out.append((path + '.len', got if not isinstance(got, list) else len(got), len(want)))
            return
        for i, (g, w) in enumerate(zip(got, want)):
            diff('%s[%d]' % (path, i), g, w, out)
    else:
        if got != want:
            out.append((path, got, want))


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    bad = 0
    for it in range(rounds):
        cases = [gen_case(rng) for _ in range(rng.randrange(1, 4))]
        want = [ref.run(c) for c in cases]
        got = solver.solve({'cases': cases})['cases']
        for i, (g, w) in enumerate(zip(got, want)):
            out = []
            diff('case%d' % i, g, w, out)
            if out:
                bad += 1
                print('=== MISMATCH seed=%d iter=%d case=%d' % (seed, it, i))
                print(json.dumps(cases[i])[:3000])
                for path, gv, wv in out[:12]:
                    print('  ', path, 'got=', str(gv)[:200], 'want=', str(wv)[:200])
                if bad > 3:
                    return 1
    print('done rounds=%d mismatches=%d' % (rounds, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    raise SystemExit(main())
